INSERT INTO `diet_plans` (`id`, `title`, `description`, `foods`, `kcal`, `food1_id`, `food2_id`, `food3_id`, `user_id`) VALUES
(1, 'Kiegyensúlyozott étrend', 'Egy változatos, kiegyensúlyozott étrend napi három étkezéssel. Ajánlott azoknak, akik szeretnék fenntartani az energiaszintjüket és kiegyensúlyozott táplálkozásra törekednek.', 'Tükörtojás toast kenyérrel, humusszal és zöldségekkel; Tejszínes gombás csirke tésztával; Grillezett lazac spárgával és quinoával', 1678, 2, 7, 9, 1),
(2, 'Alacsonyabb kalóriatartalmú étrend', 'Fogyókúrás célokra ajánlott étrend napi három étkezéssel. Ideális azoknak, akik alacsonyabb kalóriabevitellel szeretnének fogyni vagy súlyukat csökkenteni.', 'Fekete csokis magas protein zabkása; Pestos csirkemell zöldségekkel és rizzsel; Sült csirke zöldsalátával', 1460, 1, 6, 12, 1);

