--
-- A tábla adatainak kiíratása `exercises`
--

INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(1, 'Híd', 'Láb', 'A híd gyakorlat egy kiváló erősítő mozdulat, amely elsősorban a lábakat és a feneket célozza meg. A gyakorlat során a hátunkat a földön tartva emeljük meg a csípőt, miközben a lábunkat hajlítva tartjuk. A híd segít a farizom, a combizom és a törzs izmainak erősítésében, miközben javítja a mobilitást és stabilitást is.', 'data:image/jpeg;base64,', 'Saját testsúlyos edzés', 1),
(2, 'Felhúzás egy lábon', 'Láb', 'A felhúzás egy lábon a hát, a fenék és a comb izmokat célozza meg. A gyakorlat során az egyik lábat egyenesen tartjuk, míg a másikkal emeljük fel a testünket.', 'data:image/jpeg;base64,', 'Saját testsúlyos edzés', 1),
(3, 'Váltott kitörés ugrással', 'Láb', 'A váltott kitörés ugrással egy dinamikus gyakorlat, amely javítja az állóképességet és erősíti a lábizmokat. A gyakorlatot a kitörések váltakozása és az ugrások kombinálása jellemzi.', 'data:image/jpeg;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(4, 'Guggolás', 'Láb', 'A guggolás egy alapvető lábgyakorlat, amely segít erősíteni a combot, a feneket és a törzset. A gyakorlat során a térdek hajlítása és a csípő süllyesztése a fő 	mozdulat.', 'data:image/png;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(5, 'Váltakozó oldalirányú kitörés', 'Láb', 'A váltakozó oldalirányú kitörés egy kitűnő gyakorlat a comb, a fenék és a stabilizáló izmok erősítésére, miközben javítja az egyensúlyt.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(6, 'Váll szélességű fekvőtámasz', 'Mell', 'A váll szélességű fekvőtámasz a mellkas, a váll és a tricepsz erősítésére szolgáló alap gyakorlat.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(7, 'Széles fekvőtámasz', 'Mell', 'A széles fekvőtámasz a mellkas külső részére koncentrál, miközben a vállakat is megdolgoztatja.', 'data:image/png;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(8, 'Negatív fekvőtámasz', 'Mell', 'A negatív fekvőtámasz a fekvőtámasz egyik variációja, amely a mellkas és a tricepsz izmait célozza meg, különösen a leengedés fázisban.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(9, 'Pozitív fekvőtámasz', 'Mell', 'A pozitív fekvőtámasz a klasszikus fekvőtámasz forma, mely a mellkas és a kar izmokat erősíti.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(10, 'T fekvőtámasz', 'Mell', 'A T fekvőtámasz a fekvőtámasz egyik variációja, amely a vállakat és a mellkas külső részét célozza meg, miközben az alkarokat is erősíti.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(11, 'Fekvőtámasz', 'Kar', 'A fekvőtámasz alap gyakorlat a váll, a mellkas és a tricepsz számára. Számos variációval és nehezítéssel alkalmazható.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(12, 'Fekvőtámasz kézállásban', 'Kar', 'A kézállásos fekvőtámasz egy nehezített fekvőtámasz variáció, amely főként a vállakat, karokat és a core izmokat célozza meg.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(13, 'Superman', 'Hát', 'A Superman gyakorlat a hát és a fenék izmainak erősítésére szolgál, miközben javítja a törzs stabilitását.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(14, 'Csípő hajlítás', 'Hát', 'A csípő hajlítás célja a hát alsó részének és a combizmok erősítése.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(15, 'Fordított hóangyal', 'Hát', 'A fordított hóangyal egy hátizom gyakorlat, amely segít javítani a mobilitást és erősíteni a törzset.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(16, 'Húzódzkodás', 'Hát', 'A húzódzkodás a hát, a karok és a vállak erősítésére szolgál. Alap gyakorlat, amely a felsőtest erőnlétét javítja.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(17, 'Váltott sarokérintés', 'Hát', 'A váltott sarokérintés a hasizmok erősítésére szolgál, különösen a ferde hasizomra koncentrálva.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(18, 'Hegymászó', 'Has', 'A hegymászó egy kiváló kardió gyakorlat, amely a hasizmokat és a lábakat egyaránt erősíti.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(19, 'Ollózás', 'Has', 'Az ollózás egy dinamikus gyakorlat, amely a hasizmok és a csípő flexorokat célozza meg.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(20, 'Térdfelhúzás csúszkával', 'Has', 'A térdfelhúzás csúszkával segít erősíteni a hasizmokat és javítani az állóképességet.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(21, 'Pike Up csúszkával', 'Has', 'A Pike Up csúszkával célzottan erősíti a hasizmokat és a törzset.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(22, 'Lábemelés fekve', 'Has', 'A lábemelés fekve egy remek gyakorlat a hasizmok, különösen az alsó rész erősítésére.', 'data:image/webp;base64,', 'Saját testsúlyos edzés', 1),
(23, 'Kettlebell swing', 'Láb', 'A kettlebell swing egy erősítő gyakorlat, amely a comb, a fenék és a törzs izmait dolgoztatja meg, miközben javítja az állóképességet.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(24, 'Guggolás rúddal', 'Láb', 'A guggolás rúddal egy alap edzőtermi gyakorlat, amely a lábakat, a feneket és a törzset célozza meg.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(25, 'Deadlift', 'Láb', 'A deadlift egy erősítő gyakorlat, amely a hát, a lábak és a fenék izmait célozza meg.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(26, 'Lábtolás', 'Láb', 'A lábtolás egy edzőteremben végzett gyakorlat, amely a lábakat és a feneket erősíti meg.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(27, 'Guggolás Smith gépen', 'Láb', 'A Smith gépen végzett guggolás egy gépesített gyakorlat, amely a combokat és a feneket célozza meg.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(28, 'Kettlebell goblet guggolás', 'Láb', 'A kettlebell goblet guggolás a lábakat és a feneket erősíti meg, miközben a törzset is stabilizálja.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(29, 'Fekvenyomás', 'Mell', 'A Bench Press egy alapvető mellizom-erősítő gyakorlat, amely segíti a felsőtest izomzatának fejlesztését és az erőnövelést.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(30, 'Vállból nyomás', 'Kar', 'A Vállból nyomás kiváló gyakorlat a vállizmok és a felsőtest erőnlétének növelésére, elősegítve a vállak stabilitását és erejét.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(31, 'Mellhez húzás', 'Hát', 'A Mellhez húzás hatékony hátizom-erősítő gyakorlat, amely javítja a felső háti régió izomzatát és segít a húzó mozgások fejlesztésében.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(32, 'Evezés csigán', 'Hát', 'A Mellhez húzás hatékony hátizom-erősítő gyakorlat, amely javítja a felső háti régió izomzatát és segít a húzó mozgások fejlesztésében.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(33, 'Lábfeszítés gépen', 'Láb', 'A Lábfeszítés gépen segíti a combfeszítő izmok izolált erősítését, ami elengedhetetlen a láb erejének és állóképességének növeléséhez.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(34, 'Bicepsz hajlítás', 'Kar', 'A Bicepsz hajlítás az egyik legjobb izolációs gyakorlat a bicepsz fejlesztésére, amely segít az erőnövelésben és az esztétikus karizom kialakításában.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1),
(35, 'Tricepsz letolás', 'Kar', 'A Tricepsz letolás hatékony tricepsz gyakorlat, amely elősegíti a kar hátsó részének erősítését és tónusossá tételét.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(36, 'Lábhajlítás gépen', 'Láb', 'A Lábhajlítás gépen izoláltan dolgoztatja meg a combhajlító izmokat, hozzájárulva a láb erősebbé és stabilabbá tételéhez.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);
INSERT INTO `exercises` (`exercise_id`, `exercise_name`, `muscle_group`, `description`, `img`, `type`, `user_id`) VALUES
(37, 'Bolgár guggolás', 'Láb', 'A Bolgár guggolás egy egylábas guggolás variáció, amely fejleszti az egyensúlyt, az erőt és a lábizmokat egyaránt.', 'data:image/webp;base64,', 'Edzőtermi edzés', 1);

