-- Tábla szerkezet ehhez a táblához `foods`
--

CREATE TABLE `foods` (
  `food_id` int(11) NOT NULL,
  `name` varchar(255) NOT NULL,
  `description` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  `calorie` int(11) NOT NULL,
  `fat` double NOT NULL,
  `protein` double NOT NULL,
  `carb` double NOT NULL,
  `img` longtext DEFAULT NULL,
  `recipe` varchar(255) NOT NULL,
  `user_id` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- A tábla adatainak kiíratása `foods`
--

INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(1, 'Fekete csokis magvas protein zabkása', 'Egy magas fehérjetartalmú, lassan felszívódó szénhidrátokban gazdag reggeli, ami ideális az aktív napok megkezdéséhez vagy edzés előtt. Ajánlott sportolóknak és egészségtudatos életmódot követőknek.', 'reggeli', 494, 19.7, 36, 40.5, 'data:image/jpeg;base64,', 'Keverd össze az apró szemű zabot, csokis proteinport, chia magot, diót és mogyorót egy tálban. Adj hozzá mandulatejet, majd főzd lassú tűzön 5-7 percig, amíg sűrű nem lesz. Tálalás előtt szórd meg aprított fekete csokival.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(2, 'Tükörtojás toast kenyérrel, humusszal és zöldségekkel', 'Egy gyorsan elkészíthető, kiegyensúlyozott reggeli, ami fehérjében és rostban gazdag. Ideális azoknak, akik energiát szeretnének gyűjteni egy hosszú munkanapra.', 'reggeli', 558, 25, 32.5, 43, 'data:image/jpeg;base64,', 'Süss tükörtojást kevés olajon. Pirítsd meg a toast kenyereket. Kend meg őket humusszal, majd helyezd rájuk a tükörtojásokat. Tálalás előtt adj hozzá sárgápaprikát és szeletelt paradicsomot.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(3, 'Gyümölcs smoothie', 'Egy tápláló és vitaminokban gazdag ital, ami ideális a nap bármely szakában. Különösen ajánlott sportolóknak és gyors energiaforrásként szolgál.', 'reggeli', 615, 10.5, 41.5, 76, 'data:image/jpeg;base64,', 'Turmixold össze a banánt, fagyasztott bogyós gyümölcsöket, mandulatejet és fehérjeport sima állagúvá. Adj hozzá mézet és mogyoróvajat ízlés szerint, majd tálalás előtt szórj a tetejére friss gyümölcsöket.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(4, 'Protein amerikai palacsinta gyümölcsökkel', 'Egy fehérjében gazdag, ízletes reggeli, amely kielégíti az édesség utáni vágyat anélkül, hogy lemondanál az egészséges táplálkozásról. Kiváló választás diétázóknak.', 'reggeli', 610, 5.5, 50.5, 84, 'data:image/jpeg;base64,', 'Keverd össze a zabot, fehérjeport, mandulatejet és görög joghurtot sūrű palacsintatészta állagúvá. Süss kis adagokat egy tapadásmentes serpenyőben. Tálalás előtt halmozz a palacsinták tetejére friss gyümölcsöket.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(5, 'Reggeli taco zöldségekkel', 'Egy ízletes és színes reggeli, amely tele van vitaminokkal és fehérjével. Ideális azoknak, akik szeretik a változatosságot a reggeli étkezéseikben.', 'reggeli', 709, 25, 44, 67, 'data:image/jpeg;base64,', 'Melegítsd fel a tortilla lapokat. Töltsd meg őket felvert tojás és tojásfehérje keverékéből készített rántottával. Adj hozzá paprikát, rukkolát és salsa szószt. Tekerd fel és azonnal fogyaszd.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(6, 'Pestós csirkemell zöldségekkel és rizzsel', 'Egy alacsony zsírtartalmú, fehérjében gazdag ebéd, amely tökéletes az aktív életmódhoz. Ajánlott azoknak, akik izomtömeg-növelésre vagy fogyásra törekednek.', 'ebed', 556, 12, 51, 44, 'data:image/jpeg;base64,', 'Süss csirkemellfilét kevés olajon, majd kend meg zsírszegény pestóval. Köretként tálald főtt rizzsel és párolt zöldségekkel, mint lilahagyma, cukkini és zöldbab.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(7, 'Tejszínes gombás csirke tésztával', 'Egy ízletes és laktató ebéd, ami gazdag fehérjében és szénhidrátban. Kiváló választás hosszú munkanapok vagy edzés után.', 'ebed', 636, 10, 64, 61, 'data:image/jpeg;base64,', 'Süss csirkemell csíkokat olajon, majd adj hozzá felszeletelt gombát. Párold puhára, majd keverd össze tejszínnel és fokhagymával. Főtt tésztával tálald.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(8, 'Egészséges hamburger', 'Egy klasszikus gyorsétel egészséges változata, amely tele van fehérjével és kevesebb zsírt tartalmaz. Ideális családi ebédekhez vagy hétvégi összejövetelekhez.', 'ebed', 532, 19, 46, 33, 'data:image/jpeg;base64,', 'Grillezd meg a pulykadarálthúsból készített pogácsákat. Helyezd őket a pirított hamburger zsemle alsó felére. Adj hozzá salátát, light sajtot és light ketchupot, majd takard be a zsemle felső felével.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(9, 'Grillezett lazac spárgával és quinoával', 'Egy omega-3 zsírsavakban gazdag vacsora, ami támogatja az agy és a szív egészségét. Ajánlott azoknak, akik egészségtudatos életmódot követnek.', 'vacsora', 540, 20, 40, 35, 'data:image/jpeg;base64,', 'Grillezd meg a lazacot olajjal megkenve. Közben párold a spárgát, majd köretként tálald főtt quinoával.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(10, 'Marhahúsos taco teljes kiőrlésű tortillában', 'Egy ízletes és tápláló vacsora, amely tele van fehérjével és komplex szénhidrátokkal. Kiváló választás aktív életmódhoz.', 'vacsora', 620, 25, 45, 50, 'data:image/jpeg;base64,', 'Süssd meg a marhahús darált húsát, majd töltsd a teljes kiőrlésű tortillákba. Adj hozzá zöldségeket, mint paprika és hagyma.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(11, 'Zöldséges curry barna rizzsel', 'Egy fűszeres, zöldségekben gazdag étel, ami tele van vitaminokkal és rostokkal. Vegetáriánusoknak és egészséges vacsorára vágyóknak ajánlott.', 'vacsora', 490, 15, 10, 80, 'data:image/jpeg;base64,', 'Párold meg a zöldségeket, mint sárgarépa, brokkoli és paprika. Adj hozzá kókusztejet és curry fűszert, majd főzd puhára. Tálald főtt barna rizzsel.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(12, 'Sült csirke zöldsalátával', 'Egy könnyű és egészséges vacsora, amely alacsony kalóriatartalmú, mégis laktató. Ideális diétázóknak és azoknak, akik kiegyensúlyozott étrendet követnek.', 'vacsora', 450, 10, 35, 45, 'data:image/jpeg;base64,', 'Süsd meg a csirkemellet olívaolajon, közben készíts friss zöldsalátát. Öntsd le citromlével és kevés olívaolajjal, majd tálald a csirke mellé.', 1);
INSERT INTO `foods` (`food_id`, `name`, `description`, `type`, `calorie`, `fat`, `protein`, `carb`, `img`, `recipe`, `user_id`) VALUES
(13, 'Vega lasagne', 'Egy ínycsiklandó vegetáriánus étel, amely gazdag zöldségekkel, sajttal és tésztával készül. Kiváló választás azoknak, akik húsmentes fogásra vágynak.', 'vacsora', 520, 18, 25, 60, 'data:image/jpeg;base64,', 'Főzd meg a lasagne tésztát, majd rétegezd fel egy tűzálló edénybe a zöldségeket, sajtot és tésztát. Süssük a sütőben, amíg a sajt aranybarnára nem olvad.', 1);

