--
-- Tábla szerkezet ehhez a táblához `workout_plans`
--

CREATE TABLE `workout_plans` (
  `id` int(11) NOT NULL,
  `title` varchar(255) NOT NULL,
  `goodFor` varchar(255) NOT NULL,
  `description` varchar(255) NOT NULL,
  `type` varchar(255) NOT NULL,
  `exercise1_id` int(11) DEFAULT NULL,
  `exercise2_id` int(11) DEFAULT NULL,
  `exercise3_id` int(11) DEFAULT NULL,
  `exercise4_id` int(11) DEFAULT NULL,
  `exercise5_id` int(11) DEFAULT NULL,
  `user_id` int(11) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- A tábla adatainak kiíratása `workout_plans`
--

INSERT INTO `workout_plans` (`id`, `title`, `goodFor`, `description`, `type`, `exercise1_id`, `exercise2_id`, `exercise3_id`, `exercise4_id`, `exercise5_id`, `user_id`) VALUES
(1, 'Kezdő teljes test edzés', 'Kezdőknek, akik erősíteni szeretnék az egész testüket.', 'Guggolás – 3x12 ismétlés\\r\\nVáll szélességű fekvőtámasz – 3x10 ismétlés\\r\\nHíd – 3x30 másodperc\\r\\nVáltott kitörés ugrással – 3x10 ismétlés/láb\\r\\nHegymászó – 3x15 ismétlés', 'Saját testsúlyos edzés.', 4, 6, 1, 3, 20, 1),
(2, 'Erő és Stabilitás', 'Ez az edzésterv a láb- és törzsizmok fejlesztésére koncentrál, az erő, a stabilitás és a funkcionális teljesítmény növelése érdekében. Ideális a teljes alsótest megerősítéséhez, valamint a core izomzat stabilitásának javításához.', 'Guggolás rúddal: 4x10 ismétlés\r\nDeadlift (Felhúzás): 4x8 ismétlés\r\nLábtolás: 3x12 ismétlés\r\nKettlebell goblet guggolás: 3x15 ismétlés\r\nSmith gépen végzett guggolás: 3x10 ismétlés', 'Edzőtermi edzés', 27, 28, 29, 31, 30, 1),
(3, 'Kezdő felső test edzés', 'Ez a program a mellkas és tricepsz izomcsoportjait célozza meg. Az erő és izomtónus javítására alkalmas, miközben hangsúlyt fektet a toló mozdulatok erősítésére és az izomdefiníció fejlesztésére.', 'Bench Press (Fekvenyomás): 4x8 ismétlés\r\nSzéles fekvőtámasz: 3x15 ismétlés\r\nNegatív fekvőtámasz: 3x12 ismétlés\r\nPozitív fekvőtámasz: 3x12 ismétlés', 'Edzőtermi edzés', 34, 7, 8, 9, 0, 1),
(4, 'Hátépítés és Tartás', 'Ez az edzésterv a hát és a bicepsz erősítésére szolgál, különös figyelmet fordítva a testtartás javítására és az erős, esztétikus felsőtest kialakítására. Kiválóan alkalmas a húzó mozdulatok erejének növelésére is.', 'Lat Pulldown (Mellhez húzás): 4x10 ismétlés\r\nCable Row (Evezés): 3x12 ismétlés\r\nSuperman: 3x20 mp tartás\r\nHúzódzkodás: 3x amennyi megy', 'Edzőtermi edzés', 36, 37, 14, 18, 0, 1),
(5, 'Mellkas és Váll Erősítés', 'A mellkas és váll izmok erősítésére szolgáló edzésterv, mely a felsőtest stabilitásának és erejének fejlesztésére összpontosít.', 'Váll szélességű fekvőtámasz: 3x12 ismétlés\r\nSzéles fekvőtámasz: 3x10 ismétlés\r\nNegatív fekvőtámasz: 3x8 ismétlés\r\nT fekvőtámasz: 3x6 ismétlés/oldal\r\nFekvőtámasz kézállásban: 3x30 mp', 'Saját testsúlyos edzés.', 6, 7, 8, 10, 13, 1),
(6, 'Alsótest', 'Az alsótest izmainak erősítésére és tonizálására koncentráló edzésterv. Segít a combok, fenék és törzs stabilizáló izmainak fejlesztésében.', 'Híd: 3x12 ismétlés\r\nFelhúzás egy lábon: 3x10 ismétlés/oldal\r\nVáltott kitörés ugrással: 4x15 ismétlés/oldal\r\nGuggolás: 4x15 ismétlés\r\nVáltakozó oldalirányú kitörés: 3x12 ismétlés/oldal', 'Saját testsúlyos edzés.', 1, 2, 3, 4, 5, 1);

